/* Slide Studio — local-first, dependency-free authoring surface. */
'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID();
const layouts=['title','text','split','media','quote','comparison'];
const layoutNames={title:'タイトル',text:'文章',split:'素材＋文章',media:'全画面素材',quote:'引用・問い',comparison:'比較'};
function newSlide(layout='text'){return{id:uid(),layout,title:'新しいスライド',body:'ここに内容を入力',eyebrow:'',notes:'',source:'',assetId:'',media:{start:0,end:0,volume:1,autoplay:true,loop:false,muted:false,fit:'contain'},fragment:false,cue:'',leftTitle:'Before',leftBody:'',rightTitle:'After',rightBody:''};}
function sample(){const slides=[newSlide('title'),newSlide('split'),newSlide('quote'),newSlide('comparison'),newSlide('text')];Object.assign(slides[0],{title:'表現を、\n編集可能に。',eyebrow:'SLIDE STUDIO / YOUR WORKSPACE',body:'映像と音声、言葉とコード。\n自分の発表を、自分の道具でつくる。',notes:'これは編集用のサンプルです。タイトルや内容を自分の発表に置き換えてください。'});Object.assign(slides[1],{title:'素材から、話を組み立てる',eyebrow:'01 / MEDIA',body:'画像・動画・音声を素材パネルへ追加。\n再生位置、音量、ループを設定して、\nスライドと一緒にコントロール。',notes:'左の素材パネルから動画を追加して、このスライドへ割り当てる。'});Object.assign(slides[2],{title:'完成した像だけでなく、\nその過程をどう伝えるか。',eyebrow:'02 / QUESTION',body:'発表を、作品の延長として考える。'});Object.assign(slides[3],{title:'同じデータを、人間とAIで編集する',eyebrow:'03 / WORKFLOW',leftTitle:'Canvas',leftBody:'画面で内容を確認\n文章や素材を調整\n発表しながら検証',rightTitle:'deck.json',rightBody:'構成と内容を記述\nエージェントから編集\n差分を確認して適用'});Object.assign(slides[4],{title:'次の発表を、ここから。',eyebrow:'04 / START',body:'1. タイトルと内容を編集\n2. 素材を追加して配置\n3. 発表者ノートを記入\n4. プロジェクトを保存、発表・共有',fragment:true});return{version:1,name:'Untitled presentation',author:'SOGEN HANDA',theme:{background:'#111318',foreground:'#f2f3f6',accent:'#86b6ff',font:'sans-serif'},slides,assets:[]};}
let deck=sample(),index=0,panel='slides',view='canvas',history=[],future=[],logs=[],db=null,saveTimer,dirtySource=false,presenting=false,fragmentStep=0,channel=null,bridge=null,bridgeURL='ws://127.0.0.1:4317',bridgeToken='',localConnected=false,remoteRevision='',dragIndex=null;
const isPresenter=new URLSearchParams(location.search).has('presenter');
function log(message,type='ok'){logs.push({time:new Date().toLocaleTimeString('ja-JP'),message,type});logs=logs.slice(-100);if($('#logs'))$('#logs').innerHTML=logs.map(l=>`<div class="log-${l.type}"><span class="log-time">${l.time}</span> ${esc(l.message)}</div>`).join('');if($('#logs'))$('#logs').scrollTop=$('#logs').scrollHeight;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3200);}
function current(){return deck.slides[index];}
function validate(d){if(!d||d.version!==1||typeof d.name!=='string'||!Array.isArray(d.slides)||!d.slides.length||!Array.isArray(d.assets))throw Error('version:1、name、1枚以上のslides、assetsが必要です。');if(d.slides.length>500)throw Error('スライドは最大500枚です。');const ids=new Set();for(const s of d.slides){if(typeof s.id!=='string'||ids.has(s.id))throw Error('スライドIDは重複しない文字列にしてください。');ids.add(s.id);if(!layouts.includes(s.layout)||typeof s.title!=='string'||typeof s.body!=='string')throw Error('各スライドに有効なlayout、title、bodyが必要です。');if(s.media){for(const k of ['start','end','volume'])if(s.media[k]!=null&&(!Number.isFinite(s.media[k])||s.media[k]<0))throw Error('再生設定は0以上の数値が必要です。');if(s.media.volume>1)throw Error('音量は0〜1です。');if(s.media.end>0&&s.media.end<=s.media.start)throw Error('終了位置は開始位置より後にしてください。');}}const aid=new Set();for(const a of d.assets){if(typeof a.id!=='string'||aid.has(a.id)||!['image','video','audio'].includes(a.type)||typeof a.name!=='string'||typeof a.src!=='string')throw Error('素材のid、type、name、srcを確認してください。');safeSrc(a.src);aid.add(a.id);}if(!d.theme||!['background','foreground','accent'].every(k=>/^#[0-9a-f]{6}$/i.test(d.theme[k])))throw Error('テーマの色は #RRGGBB 形式で指定してください。');return d;}
function safeSrc(src){if(!src)return'';if(/^(data:(image|video|audio)\/[a-z0-9.+-]+(?:;[^,]*)?,|blob:|https?:\/\/)/i.test(src)||/^media\/[\w./%-]+$/.test(src))return src;throw Error('素材は画像・動画・音声のdata URL、http(s) URL、media/パスにしてください。');}
function snapshot(){history.push(JSON.stringify(deck));if(history.length>60)history.shift();future=[];}
function changed({render=true,save=true}={}){if(render)renderAll();if(save){clearTimeout(saveTimer);$('#save-state')&&($('#save-state').textContent='保存中…');saveTimer=setTimeout(saveDeck,400);}broadcast();}
function updateSlide(key,value,render=true){snapshot();current()[key]=value;changed({render});}
async function initDB(){return new Promise((resolve,reject)=>{const request=indexedDB.open('slide-studio-v1',1);request.onupgradeneeded=()=>request.result.createObjectStore('workspace');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function stored(key){return new Promise((resolve,reject)=>{const r=db.transaction('workspace').objectStore('workspace').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
async function saveDeck(){if(!db){$('#save-state')&&($('#save-state').textContent='ファイル保存が必要');return;}try{await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(deck,'deck');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});$('#save-state')&&($('#save-state').textContent='自動保存済み');}catch(e){log('自動保存できません。プロジェクトをファイル保存してください。','warn');$('#save-state')&&($('#save-state').textContent='保存失敗');}}
function mediaHTML(s,play=false,assets=deck.assets){const a=assets.find(a=>a.id===s.assetId);if(!a)return'<div class="media-wrap"><div class="missing">素材をここに<br>左の素材パネルから追加・割り当て</div></div>';let src='';try{src=safeSrc(a.src);}catch{}const m=s.media||{},fit=m.fit==='cover'?'cover':'contain';if(a.type==='image')return`<div class="media-wrap"><img src="${esc(src)}" alt="${esc(a.name)}" style="object-fit:${fit}"></div>`;if(a.type==='audio')return`<div class="media-wrap"><audio src="${esc(src)}" controls ${m.muted?'muted':''} preload="metadata" data-media="${esc(s.id)}"></audio></div>`;return`<div class="media-wrap"><video src="${esc(src)}" ${play?'controls':''} playsinline ${m.muted?'muted':''} preload="metadata" style="object-fit:${fit}" data-media="${esc(s.id)}"></video></div>`;}
function slideHTML(s,{play=false,step=999,number=0,assets=deck.assets}={}){const t=deck.theme;let body='';const content=s.fragment? s.body.split('\n').map((line,i)=>`<div class="fragment ${i<step?'visible':''}">${esc(line)||'&nbsp;'}</div>`).join(''):esc(s.body);const head=`${s.eyebrow?`<div class="eyebrow">${esc(s.eyebrow)}</div>`:''}<h1>${esc(s.title)}</h1>`;if(s.layout==='media'){body=mediaHTML(s,play,assets)+`<div class="overlay-title">${esc(s.title)}</div>`;}else if(s.layout==='split'){body=`${s.eyebrow?`<div class="eyebrow">${esc(s.eyebrow)}</div>`:''}<div class="split-content"><div><h1>${esc(s.title)}</h1><div class="slide-body">${content}</div></div>${mediaHTML(s,play,assets)}</div>`;}else if(s.layout==='comparison'){body=head+`<div class="comparison"><div class="compare-card"><strong>${esc(s.leftTitle)}</strong>${esc(s.leftBody)}</div><div class="compare-card"><strong>${esc(s.rightTitle)}</strong>${esc(s.rightBody)}</div></div>`;}else{body=head+`<div class="slide-body">${content}</div>`;}return`<article class="slide ${esc(s.layout)}" style="--slide-bg:${t.background};--slide-fg:${t.foreground};--slide-accent:${t.accent};font-family:${t.font==='serif'?'Georgia,serif':t.font==='mono'?'ui-monospace,monospace':'Inter,-apple-system,BlinkMacSystemFont,sans-serif'}">${body}<div class="slide-footer"><span>${esc(s.source||deck.author)}</span><span>${String(number+1).padStart(2,'0')}</span></div></article>`;}
function renderStage(){const s=current();if(!s)return;$('#stage').innerHTML=slideHTML(s,{number:index});$('#page-label').textContent=`${index+1} / ${deck.slides.length}`;$('#breadcrumbs').textContent=`${deck.name}  ›  slides  ›  ${s.id.slice(0,8)}  ›  ${layoutNames[s.layout]}`;$('#notes').value=s.notes||'';if(presenting){const root=$('#presentation-stage');root.innerHTML=slideHTML(s,{play:true,step:fragmentStep,number:index});$('#presentation-page').textContent=`${index+1} / ${deck.slides.length}`;setupMedia(root,s,true);}fitStage();}
function fitStage(){const area=$('#canvas-area'),stage=$('#stage');if(!area||area.hidden)return;const width=Math.max(180,Math.min(area.clientWidth-56,(area.clientHeight-56)*16/9,1100));const z=$('#zoom').value;stage.style.width=(z==='fit'?width:960*Number(z))+'px';}
function renderAll(){if(isPresenter)return;$('#deck-name').value=deck.name;renderStage();renderSidebar();renderInspector();if(view==='source'&&!dirtySource)$('#source-editor').value=JSON.stringify(deck,null,2);if(view==='overview')renderOverview();$('#status-right').textContent=`${deck.slides.length} slides · ${deck.assets.length} assets · 16:9`;}
function selectSlide(i){index=Math.max(0,Math.min(i,deck.slides.length-1));fragmentStep=0;renderAll();broadcast();sendCue();}
function advance(){if(presenting&&current().fragment&&fragmentStep<current().body.split('\n').length){fragmentStep++;renderStage();broadcast();return;}selectSlide(index+1);}
function previous(){if(presenting&&fragmentStep>0){fragmentStep--;renderStage();broadcast();return;}selectSlide(index-1);}
function field(label,key,value,type='text'){return`<div class="field"><label>${label}</label>${type==='textarea'?`<textarea data-field="${key}">${esc(value)}</textarea>`:`<input type="${type}" data-field="${key}" value="${esc(value)}" ${type==='number'?'min="0" step="0.1"':''}>`}</div>`;}
function renderInspector(){const s=current(),m=s.media||{};$('#inspector-body').innerHTML=`<section class="inspector-section"><h3>SLIDE / ${String(index+1).padStart(2,'0')}</h3><div class="field"><label>レイアウト</label><select data-field="layout">${layouts.map(l=>`<option value="${l}" ${s.layout===l?'selected':''}>${layoutNames[l]}</option>`).join('')}</select></div>${field('見出し','title',s.title,'textarea')}${field('小見出し','eyebrow',s.eyebrow||'')}${field('本文','body',s.body,'textarea')}${s.layout==='comparison'?field('左の見出し','leftTitle',s.leftTitle)+field('左の本文','leftBody',s.leftBody,'textarea')+field('右の見出し','rightTitle',s.rightTitle)+field('右の本文','rightBody',s.rightBody,'textarea'):''}${field('出典 / フッター','source',s.source||'')}<label class="check"><input type="checkbox" data-field="fragment" ${s.fragment?'checked':''}>本文を1行ずつ表示</label><div class="button-row"><button data-action="duplicate">複製</button><button data-action="move-up">上へ</button><button data-action="move-down">下へ</button><button class="danger" data-action="delete-slide">削除</button></div></section><section class="inspector-section"><h3>MEDIA</h3><div class="field"><label>素材</label><select data-field="assetId"><option value="">未設定</option>${deck.assets.map(a=>`<option value="${esc(a.id)}" ${s.assetId===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field-row">${field('開始 / 秒','media.start',m.start||0,'number')}${field('終了 / 0=末尾','media.end',m.end||0,'number')}</div><div class="field"><label>音量 ${Math.round((m.volume??1)*100)}%</label><input type="range" min="0" max="1" step="0.01" data-field="media.volume" value="${m.volume??1}"></div>${['autoplay','loop','muted'].map(k=>`<label class="check"><input type="checkbox" data-field="media.${k}" ${m[k]?'checked':''}>${{autoplay:'スライド表示時に再生',loop:'ループ',muted:'ミュート'}[k]}</label>`).join('')}<div class="field"><label>画像・動画の収まり</label><select data-field="media.fit"><option value="contain" ${m.fit!=='cover'?'selected':''}>全体を表示</option><option value="cover" ${m.fit==='cover'?'selected':''}>画面を埋める</option></select></div></section><section class="inspector-section"><h3>TOUCHDESIGNER CUE</h3>${field('スライド表示時に送る名前','cue',s.cue||'')}</section><section class="inspector-section"><h3>DECK THEME</h3><div class="field-row">${field('背景','theme.background',deck.theme.background,'color')}${field('文字','theme.foreground',deck.theme.foreground,'color')}</div>${field('アクセント','theme.accent',deck.theme.accent,'color')}<div class="field"><label>書体</label><select data-field="theme.font">${['sans-serif','serif','mono'].map(f=>`<option ${deck.theme.font===f?'selected':''}>${f}</option>`).join('')}</select></div>${field('発表者','author',deck.author||'')}</section>`;}
function renderSidebar(){const titles={slides:'EXPLORER',assets:'ASSETS',search:'SEARCH',agent:'AGENT EDIT',bridge:'CONNECTIONS'};$('#panel-title').textContent=titles[panel];$$('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel===panel));const root=$('#sidebar-body');if(panel==='slides'){root.innerHTML=deck.slides.map((s,i)=>`<div class="slide-row ${index===i?'active':''}" data-slide="${i}" draggable="true"><span class="number">${String(i+1).padStart(2,'0')}</span><div class="thumb">${slideHTML(s,{number:i})}</div><div class="slide-info"><strong>${esc(s.title.split('\n')[0])}</strong><small>${layoutNames[s.layout]}</small></div></div>`).join('')+'<div class="sidebar-footer"><button data-action="add">＋ スライド</button><button data-action="import">開く</button><button data-action="new">新規</button></div>';}
else if(panel==='assets'){root.innerHTML=`<div class="sidebar-footer"><button class="primary" data-action="upload">＋ 素材を追加</button><button data-action="asset-url">URL</button></div><div class="asset-list">${deck.assets.length?deck.assets.map(a=>`<div class="asset-card">${a.type==='image'?`<img src="${esc(a.src)}" alt="${esc(a.name)}">`:''}<strong>${esc(a.name)}</strong><small>${a.type.toUpperCase()} · ${a.size?formatBytes(a.size):'URL'}</small><div><button data-assign="${esc(a.id)}">このスライドへ</button><button class="danger" data-remove-asset="${esc(a.id)}">削除</button></div></div>`).join(''):'<div class="empty">画像・動画・音声をドロップするか、「素材を追加」から読み込んでください。</div>'}</div>`;}
else if(panel==='search'){root.innerHTML='<div class="panel-content"><input id="search" placeholder="スライド・ノートを検索" aria-label="スライド検索"></div><div id="search-results"></div>';}
else if(panel==='agent'){root.innerHTML=`<div class="panel-content"><h3>AIと同じデータを編集</h3><p>deck.jsonをAIへ渡し、変更後のJSONまたは操作の配列を貼り付けます。差分を確認して適用できます。</p><button class="primary" data-action="copy-agent">指示＋データをコピー</button><h3>変更を読み込む</h3><textarea id="agent-input" placeholder='[{"op":"update","id":"スライドID","changes":{"title":"新しい見出し"}}]' spellcheck="false" aria-label="AIの変更JSON"></textarea><button class="primary" data-action="review-agent">変更を確認</button><p>対応操作：update / add / delete / move / theme。全文のdeck.jsonも読み込めます。</p><button data-action="download-schema">データ形式を保存</button></div>`;}
else if(panel==='bridge'){root.innerHTML=`<div class="panel-content"><h3>Local bridge</h3><p>ローカル版のserver.mjsを起動すると、AIによるファイル編集とTouchDesignerのキュー送信を接続できます。</p><div class="field"><label>WebSocket URL</label><input id="bridge-url" value="${esc(bridgeURL)}"></div><div class="field"><label>接続トークン</label><input id="bridge-token" type="password" value="${esc(bridgeToken)}" autocomplete="off"></div><button class="primary" data-action="connect-bridge">${bridge?'切断':'接続'}</button><button data-action="test-cue">キューテスト</button><p>HTTPSの共有版からローカル接続できない場合は、ローカル版で接続してください。</p><button data-action="bridge-help">接続手順</button></div>`;}}
function renderOverview(){$('#overview-area').innerHTML=deck.slides.map((s,i)=>`<div class="overview-card" data-slide="${i}"><div class="thumb">${slideHTML(s,{number:i})}</div><p>${String(i+1).padStart(2,'0')} / ${esc(s.title.split('\n')[0])}</p></div>`).join('');}
function setView(v){if(view==='source'&&dirtySource&&v!=='source'){showModal('<h2>未適用の変更があります</h2><p>deck.jsonタブで変更を適用するか、元のデータに戻してください。</p><div class="modal-actions"><button data-action="discard-source">変更を破棄</button><button data-action="close-modal">編集を続ける</button></div>');return;}view=v;$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));$('#canvas-area').hidden=v!=='canvas';$('#source-area').hidden=v!=='source';$('#overview-area').hidden=v!=='overview';if(v==='source')$('#source-editor').value=JSON.stringify(deck,null,2);renderAll();}
function undo(){if(!history.length)return;future.push(JSON.stringify(deck));deck=JSON.parse(history.pop());index=Math.min(index,deck.slides.length-1);dirtySource=false;changed();log('変更を元に戻しました。');}
function redo(){if(!future.length)return;history.push(JSON.stringify(deck));deck=JSON.parse(future.pop());index=Math.min(index,deck.slides.length-1);changed();}
function moveSlide(from,to){if(to<0||to>=deck.slides.length||to===from)return;snapshot();const[s]=deck.slides.splice(from,1);deck.slides.splice(to,0,s);index=to;changed();}
function formatBytes(n){return n>1e6?(n/1e6).toFixed(1)+' MB':Math.round(n/1000)+' KB';}
async function addFiles(files){const additions=[];for(const f of files){const type=f.type.split('/')[0];if(!['image','video','audio'].includes(type)){log(`${f.name}: 対応していない形式です。`,'warn');continue;}if(f.size>200*1024*1024){log(`${f.name}: 200 MB以下にしてください。`,'warn');continue;}const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});additions.push({id:uid(),name:f.name,type,src,size:f.size});}if(additions.length){snapshot();deck.assets.push(...additions);panel='assets';changed();log(`${additions.length}個の素材を追加しました。`);toast('素材を追加しました');}}
function download(name,content,type='application/json'){const a=document.createElement('a'),url=URL.createObjectURL(content instanceof Blob?content:new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function fileName(){return deck.name.replace(/[\\/:*?"<>|]/g,'-')||'presentation';}
function showModal(html){$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function closeModal(){$('#modal').close();}
function showExport(){showModal(`<h2>書き出し・共有</h2><button class="export-option" data-action="export-json"><strong>プロジェクト .slide</strong><small>素材、設定、ノートをすべて保存。別の端末でも読み込めます。</small></button><button class="export-option" data-action="export-html"><strong>発表・共有用 HTML</strong><small>素材を含む単独ファイル。ブラウザで開けます。発表者ノートは含みません。</small></button><button class="export-option" data-action="export-md"><strong>Markdown</strong><small>文章・ノート・素材の参照を、AIや他のツールに渡します。</small></button><button class="export-option" data-action="export-pdf"><strong>PDF / 印刷</strong><small>動画・音声は静止した枠で表示。ブラウザの印刷からPDF保存。</small></button><div class="modal-actions"><button data-action="close-modal">閉じる</button></div>`);}
async function loadCSS(){if(globalThis.STUDIO_CSS)return globalThis.STUDIO_CSS;const r=await fetch('style.css');if(!r.ok)throw Error('書き出し用スタイルを読み込めません');return r.text();}
async function exportHTML(){
 const css=await loadCSS();
 const embeddedAssets=await Promise.all(deck.assets.map(async a=>{if(!a.src.startsWith('media/'))return a;const r=await fetch(a.src);if(!r.ok)throw Error('素材を埋め込めません: '+a.name);const blob=await r.blob();const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});return {...a,src};}));
 const config=JSON.stringify(deck.slides.map(s=>({media:s.media||{},fragment:!!s.fragment,lines:s.body.split('\n').length}))).replace(/</g,'\\u003c');
 const slides=deck.slides.map((s,i)=>`<section class="viewer-slide" data-index="${i}" ${i?'hidden':''}>${slideHTML(s,{number:i,play:true,step:0,assets:embeddedAssets})}</section>`).join('');
 const runtime=`const config=${config};let index=0,step=0,started=false;const slides=[...document.querySelectorAll('.viewer-slide')];function show(){slides.forEach((s,i)=>{s.hidden=i!==index;s.querySelectorAll('video,audio').forEach(e=>{if(i!==index)e.pause()})});document.querySelector('#page').textContent=(index+1)+' / '+slides.length;slides[index].querySelectorAll('.fragment').forEach((e,i)=>e.classList.toggle('visible',i<step));const m=config[index].media;slides[index].querySelectorAll('video,audio').forEach(e=>{e.volume=m.volume??1;const seek=()=>{e.currentTime=m.start||0;if(started&&m.autoplay)e.play().catch(()=>{})};if(e.readyState>=1)seek();else e.addEventListener('loadedmetadata',seek,{once:true});e.ontimeupdate=()=>{if(m.end>m.start&&e.currentTime>=m.end){if(m.loop){e.currentTime=m.start||0;e.play().catch(()=>{})}else e.pause()}};e.onended=()=>{if(m.loop){e.currentTime=m.start||0;e.play().catch(()=>{})}}})}function next(){if(config[index].fragment&&step<config[index].lines){step++;slides[index].querySelectorAll('.fragment').forEach((e,i)=>e.classList.toggle('visible',i<step));return}if(index<slides.length-1){index++;step=0;show()}}function prev(){if(step>0){step--;slides[index].querySelectorAll('.fragment').forEach((e,i)=>e.classList.toggle('visible',i<step));return}if(index>0){index--;step=0;show()}}document.querySelector('#start').onclick=()=>{started=true;document.querySelector('#start').hidden=true;document.documentElement.requestFullscreen?.().catch(()=>{});show()};document.querySelector('#next').onclick=next;document.querySelector('#prev').onclick=prev;document.addEventListener('keydown',e=>{if(['ArrowRight',' '].includes(e.key)){e.preventDefault();next()}if(e.key==='ArrowLeft')prev();if(e.key.toLowerCase()==='b')document.querySelector('#viewer-black').hidden=!document.querySelector('#viewer-black').hidden});show();`;
 download(fileName()+'.html',`<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(deck.name)}</title><style>${css}\nbody{background:#000;height:100dvh;display:grid;place-items:center}.viewer-slide{width:min(100vw,177.777vh);aspect-ratio:16/9}.viewer-slide[hidden]{display:none}.viewer-controls{position:fixed;bottom:14px;left:50%;transform:translateX(-50%);background:#202329dc;display:flex;gap:12px;align-items:center;border-radius:7px;padding:7px;z-index:10;opacity:.25}.viewer-controls:hover{opacity:1}#start{position:fixed;inset:40% 30%;z-index:20;background:#3277cf;font-size:20px;box-shadow:0 0 0 200vw #000a}#viewer-black{position:fixed;inset:0;background:#000;z-index:5}</style></head><body>${slides}<button id="start">▶ 発表を開始 / 音声を有効化</button><div class="viewer-controls"><button id="prev">‹</button><span id="page"></span><button id="next">›</button></div><div id="viewer-black" hidden></div><script>${runtime}</script></body></html>`,'text/html');
 log('素材を含む共有HTMLを書き出しました。URL素材はネット接続が必要です。');toast('共有用HTMLを書き出しました');
}
async function exportPDF(){const w=window.open('','slide-studio-print');if(!w){toast('印刷画面のポップアップを許可してください');return;}w.document.write('<p>印刷用スライドを準備しています…</p>');const css=await loadCSS();const pages=deck.slides.map((s,i)=>`<section class="print-page">${slideHTML(s,{number:i})}</section>`).join('');w.document.open();w.document.write(`<!doctype html><html lang="ja"><head><meta charset="utf-8"><title>${esc(deck.name)}</title><style>${css}\n@page{size:320mm 180mm;margin:0}body{overflow:visible;background:white;margin:0}.print-page{width:320mm;height:180mm;break-after:page;page-break-after:always}.print-page:last-child{break-after:auto}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}.print-button{position:fixed;right:20px;top:20px;z-index:20;background:#3277cf}@media print{.print-button{display:none}}video,audio{display:none}.media-wrap:has(video)::after,.media-wrap:has(audio)::after{content:'映像・音声素材 / 共有HTMLで再生';font-size:2cqw;color:#aaa}</style></head><body><button class="print-button" onclick="window.print()">印刷 / PDF保存</button>${pages}</body></html>`);w.document.close();log('印刷画面を開きました。PDFとして保存できます。');}
function toMarkdown(){return`---\ntitle: ${JSON.stringify(deck.name)}\nauthor: ${JSON.stringify(deck.author)}\n---\n\n`+deck.slides.map(s=>`<!-- slide-id: ${s.id}; layout: ${s.layout} -->\n# ${s.title.replaceAll('\n',' ')}\n\n${s.body}\n${s.assetId?'\n<!-- asset: '+(deck.assets.find(a=>a.id===s.assetId)?.name||s.assetId)+' -->\n':''}${s.layout==='comparison'?`\n## ${s.leftTitle}\n${s.leftBody}\n\n## ${s.rightTitle}\n${s.rightBody}\n`:''}${s.source?'\n出典: '+s.source+'\n':''}\n<!-- notes\n${s.notes||''}\n-->`).join('\n\n---\n\n');}
function fromMarkdown(text){const d=sample();d.name='Imported Markdown';d.slides=[];d.assets=[];text=text.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n/,'');for(const chunk of text.split(/\r?\n---\r?\n/)){if(!chunk.trim())continue;const s=newSlide(d.slides.length?'text':'title');s.title=chunk.match(/^# (.+)$/m)?.[1]||'Untitled';s.notes=chunk.match(/<!-- notes\s*\n([\s\S]*?)-->/)?.[1]?.trim()||'';s.body=chunk.replace(/<!--([\s\S]*?)-->/g,'').replace(/^# .+$/m,'').trim();d.slides.push(s);}return validate(d);}
async function importProject(file){try{const text=await file.text();const d=file.name.endsWith('.md')?fromMarkdown(text):validate(JSON.parse(text));snapshot();deck=d;index=0;dirtySource=false;changed();log(`${file.name}を読み込みました。`);toast('プロジェクトを読み込みました');}catch(e){toast('読み込み失敗: '+e.message);log(e.message,'warn');}}
function setupMedia(root,s,play){root.querySelectorAll('video,audio').forEach(el=>{const m=s.media||{};el.volume=Math.max(0,Math.min(1,m.volume??1));const start=Number(m.start)||0,end=Number(m.end)||0;let resetting=false;const seek=()=>{if(start&&Number.isFinite(el.duration)){if(start>=el.duration){log('開始位置が素材の長さを超えています。','warn');return;}el.currentTime=start;}};if(el.readyState>=1)seek();else el.addEventListener('loadedmetadata',seek,{once:true});el.addEventListener('timeupdate',()=>{if(end>start&&el.currentTime>=end&&!resetting){if(m.loop){resetting=true;el.currentTime=start;el.play().catch(()=>{});setTimeout(()=>resetting=false,100);}else el.pause();}});el.addEventListener('ended',()=>{if(m.loop){el.currentTime=start;el.play().catch(()=>{});}});el.addEventListener('error',()=>log('素材を読み込めません。ファイル形式やURLを確認してください。','warn'),{once:true});if(play&&m.autoplay)el.play().catch(()=>{toast('再生ボタンを押して音声・動画を開始してください');});});}
async function startPresent(){if(dirtySource){toast('JSONの変更を先に適用してください');return;}presenting=true;fragmentStep=0;$('#presentation').hidden=false;renderStage();broadcast();sendCue();try{await $('#presentation').requestFullscreen();}catch{} }
function exitPresent(){presenting=false;$('#presentation').hidden=true;$('#blackout').hidden=true;$('#presentation-stage').innerHTML='';if(document.fullscreenElement)document.exitFullscreen().catch(()=>{});broadcast();}
function broadcast(){if(channel)channel.postMessage({type:'state',deck,index,fragmentStep,presenting});}
function presenter(){const w=window.open(location.pathname+'?presenter=1','slide-studio-presenter','width=1200,height=800');if(!w){toast('発表者画面のポップアップを許可してください');return;}setTimeout(broadcast,700);}
function initChannel(){channel=new BroadcastChannel('slide-studio-'+location.pathname);channel.onmessage=e=>{const msg=e.data;if(msg.type==='request')broadcast();if(msg.type==='navigate'&&!isPresenter){if(msg.direction==='next')advance();else previous();}if(msg.type==='state'&&isPresenter){deck=msg.deck;index=msg.index;fragmentStep=msg.fragmentStep;renderPresenter();}};}
function renderPresenter(){const root=$('#presenter-root');if(!root)return;root.innerHTML=`<div><header><strong>${esc(deck.name)} / ${index+1} of ${deck.slides.length}</strong><div><button data-presenter-nav="previous">‹ 前</button><button data-presenter-nav="next" class="primary">次 ›</button></div></header><div class="current-preview">${slideHTML(current(),{number:index,step:fragmentStep})}</div><div class="speaker-note">${esc(current().notes||'発表者ノートはありません。')}</div></div><div><header><span>NEXT</span><span class="timer" id="timer">00:00</span></header><div class="next-preview">${deck.slides[index+1]?slideHTML(deck.slides[index+1],{number:index+1}):'<div class="empty">最後のスライド</div>'}</div><p class="muted">← → でスライド操作 / Rでタイマーをリセット</p></div>`;root.querySelectorAll('video,audio').forEach(el=>{el.muted=true;el.pause();});}
function applyOperations(input){if(!Array.isArray(input))return validate(input);const next=structuredClone(deck);for(const op of input){if(op.op==='update'){const s=next.slides.find(s=>s.id===op.id);if(!s)throw Error('スライドが見つかりません: '+op.id);if(!op.changes||typeof op.changes!=='object'||Array.isArray(op.changes))throw Error('changesが必要です。');if('id'in op.changes)throw Error('updateではIDを変更できません。');Object.assign(s,op.changes);}else if(op.op==='add'){const s={...newSlide(),...op.slide};next.slides.splice(Number.isInteger(op.index)?op.index:next.slides.length,0,s);}else if(op.op==='delete'){const i=next.slides.findIndex(s=>s.id===op.id);if(i<0)throw Error('削除対象が見つかりません。');next.slides.splice(i,1);}else if(op.op==='move'){const i=next.slides.findIndex(s=>s.id===op.id);if(i<0||!Number.isInteger(op.index)||op.index<0||op.index>=next.slides.length)throw Error('移動先を確認してください。');const[s]=next.slides.splice(i,1);next.slides.splice(op.index,0,s);}else if(op.op==='theme'){Object.assign(next.theme,op.changes);}else throw Error('未知の操作: '+op.op);}return validate(next);}
function reviewAgent(){try{const next=applyOperations(JSON.parse($('#agent-input').value));const before=new Map(deck.slides.map(s=>[s.id,s]));const changes=next.slides.map((s,i)=>{const old=before.get(s.id);return!old?`追加: ${s.title}`:JSON.stringify(old)!==JSON.stringify(s)?`変更: ${s.title}`:deck.slides.findIndex(x=>x.id===s.id)!==i?`移動: ${s.title}`:null;}).filter(Boolean);for(const s of deck.slides)if(!next.slides.some(x=>x.id===s.id))changes.push('削除: '+s.title);if(JSON.stringify(deck.theme)!==JSON.stringify(next.theme))changes.push('テーマを変更');if(next.name!==deck.name)changes.push('プロジェクト名を変更');if(next.author!==deck.author)changes.push('発表者を変更');if(JSON.stringify(next.assets)!==JSON.stringify(deck.assets))changes.push('素材を変更');window.pendingDeck=next;showModal(`<h2>AIの変更を確認</h2><p>${changes.length}件の変更</p><ul>${changes.map(c=>`<li>${esc(c)}</li>`).join('')||'<li>変更はありません</li>'}</ul><div class="modal-actions"><button data-action="close-modal">キャンセル</button><button class="primary" data-action="apply-agent">適用</button></div>`);}catch(e){toast(e.message);log('AI変更: '+e.message,'warn');}}
function agentPrompt(){return`Slide Studioのプロジェクトを編集してください。versionは1。スライドのidを維持し、素材のsrcを勝手に変更しないでください。layoutはtitle/text/split/media/quote/comparison。本文の改行は\\n。動画設定はmedia:{start,end,volume,autoplay,loop,muted,fit}。全文のJSON、または操作配列 [{op:"update",id,changes},{op:"add",index,slide},{op:"delete",id},{op:"move",id,index},{op:"theme",changes}] を返してください。変更する理由はJSONの外で説明してください。\n\n${JSON.stringify({...deck,assets:deck.assets.map(a=>({...a,src:a.src.startsWith('data:')?'[素材データ省略・元のsrcを維持]':a.src}))},null,2)}\n\n素材データは省略しています。返答は操作配列を推奨します。全文JSONを返す場合は省略した素材データを含めず、既存のassetsを変更しない操作配列にしてください。`;}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('コピーしました');}catch{showModal(`<h2>テキストをコピー</h2><textarea readonly>${esc(text)}</textarea><div class="modal-actions"><button data-action="close-modal">閉じる</button></div>`);}}
function checkDeck(){try{validate(deck);let warnings=0;deck.slides.forEach((s,i)=>{if(s.assetId&&!deck.assets.some(a=>a.id===s.assetId)){warnings++;log(`${i+1}枚目: 素材がありません。`,'warn');}if(s.title.length>90||s.body.length>600){warnings++;log(`${i+1}枚目: 文字量が多いです。プレビューで収まりを確認してください。`,'warn');}if(['split','media'].includes(s.layout)&&!s.assetId){warnings++;log(`${i+1}枚目: 素材が未設定です。`,'warn');}});log(`チェック完了: ${deck.slides.length}枚 / ${warnings}件の確認事項。`);toast(warnings?`${warnings}件の確認事項があります`:'データ形式に問題はありません');}catch(e){log(e.message,'warn');toast(e.message);}}
function sendCue(test=false){if(!bridge||bridge.readyState!==1)return;const s=current();bridge.send(JSON.stringify({type:'cue',slideId:s.id,index,cue:test?'test':s.cue||'',media:s.media,assetId:s.assetId,timestamp:Date.now()}));log('Cue → '+(test?'test':s.cue||s.id.slice(0,8)));}
function connectBridge(){if(bridge){bridge.close();bridge=null;renderSidebar();return;}bridgeURL=$('#bridge-url').value;bridgeToken=$('#bridge-token').value;try{const url=new URL(bridgeURL);if(!['ws:','wss:'].includes(url.protocol))throw Error('ws:// または wss:// を指定してください。');url.searchParams.set('token',bridgeToken);const ws=new WebSocket(url);bridge=ws;ws.onopen=()=>{log('Local bridgeに接続しました。');$('#status-left').textContent='● Bridge connected';ws.send(JSON.stringify({type:'subscribe',role:'editor'}));renderSidebar();};ws.onmessage=e=>{try{const msg=JSON.parse(e.data);if(msg.type==='project'){const d=validate(msg.deck);showRemoteReview(d);}else if(msg.type==='navigate'){msg.direction==='next'?advance():previous();}}catch(err){log('Bridge: '+err.message,'warn');}};ws.onclose=()=>{if(bridge===ws)bridge=null;$('#status-left').textContent='● Local workspace';log('Bridge切断');if(panel==='bridge')renderSidebar();};ws.onerror=()=>log('Bridge接続失敗。ローカル版とトークンを確認してください。','warn');}catch(e){bridge=null;toast(e.message);}}
function showRemoteReview(d){window.pendingDeck=d;showModal(`<h2>ファイルが更新されました</h2><p>AIまたは外部エディタからの変更です。現在 ${deck.slides.length}枚 → 更新後 ${d.slides.length}枚。適用すると現在の編集は履歴に保存されます。</p><div class="modal-actions"><button data-action="close-modal">今は適用しない</button><button class="primary" data-action="apply-agent">読み込む</button></div>`);}
function help(){showModal(`<h2>Slide Studio</h2><p>左でスライドや素材を選び、右で内容と再生設定を編集します。中央のdeck.jsonはAIと共有する元データです。</p><ul><li>素材は画像・動画・音声。ドラッグ＆ドロップにも対応。</li><li>発表する前に「素材再生」で音声・動画を確認。</li><li>「発表者画面」は別ウィンドウ。ノートと次のスライドを表示。</li><li>作業内容はこのブラウザに自動保存。別の端末へはプロジェクトを書き出してください。</li><li>共有用HTMLは素材を含み、ノートは除外。PDFは静止画です。</li><li>AI編集はJSONの操作配列を貼り付け、確認して適用。</li></ul><p><span class="key">⌘ S</span> ファイル保存　<span class="key">⌘ Z</span> 元に戻す　<span class="key">⌘ K</span> コマンド　<span class="key">F5</span> 発表　<span class="key">B</span> 暗転　<span class="key">Esc</span> 終了</p><div class="modal-actions"><a href="slide-studio-source.zip" download style="color:var(--accent);padding:8px">ローカル版をダウンロード</a><button class="primary" data-action="close-modal">閉じる</button></div>`);}
function palette(){const commands=[['add','新しいスライド'],['upload','素材を追加'],['import','プロジェクトを開く'],['export-menu','書き出し'],['present','発表する'],['presenter','発表者画面'],['undo','元に戻す'],['validate','プロジェクトをチェック'],['help','使い方']];showModal('<h2>コマンド</h2><input id="command-search" placeholder="コマンドを検索" aria-label="コマンド検索">'+commands.map(([a,t])=>`<button class="palette-item" data-command="${a}">${t}</button>`).join(''));$('#command-search').focus();}
const actions={add(){snapshot();deck.slides.splice(index+1,0,newSlide());index++;changed();},duplicate(){snapshot();const s=structuredClone(current());s.id=uid();deck.slides.splice(index+1,0,s);index++;changed();},'delete-slide'(){if(deck.slides.length===1){toast('最低1枚のスライドが必要です');return;}snapshot();deck.slides.splice(index,1);index=Math.min(index,deck.slides.length-1);changed();},'move-up':()=>moveSlide(index,index-1),'move-down':()=>moveSlide(index,index+1),previous,next:advance,undo,redo,present:startPresent,'exit-present':exitPresent,presenter,blackout(){if(presenting)$('#blackout').hidden=!$('#blackout').hidden;},'media-preview'(){renderStage();setupMedia($('#stage'),current(),true);},upload:()=>$('#media-input').click(),import:()=>$('#project-input').click(),new(){showModal('<h2>新しいプロジェクト</h2><p>現在のプロジェクトは、先にファイルへ保存できます。</p><div class="modal-actions"><button data-action="export-json">現在の内容を保存</button><button data-action="close-modal">キャンセル</button><button class="primary" data-action="confirm-new">新規作成</button></div>');},'confirm-new'(){snapshot();deck=sample();deck.name='New presentation';deck.slides=[newSlide('title')];index=0;dirtySource=false;changed();closeModal();},'export-menu':showExport,'export-json'(){download(fileName()+'.slide',JSON.stringify(deck,null,2));toast('プロジェクトを保存しました');},'export-md'(){download(fileName()+'.md',toMarkdown(),'text/markdown');},'export-html':()=>exportHTML(),'export-pdf':()=>exportPDF(),'apply-source'(){try{const d=validate(JSON.parse($('#source-editor').value));snapshot();deck=d;index=Math.min(index,deck.slides.length-1);dirtySource=false;$('#source-error').textContent='';changed();log('deck.jsonの変更を適用しました。');}catch(e){$('#source-error').textContent=e.message;}},'format-source'(){try{$('#source-editor').value=JSON.stringify(JSON.parse($('#source-editor').value),null,2);}catch(e){$('#source-error').textContent=e.message;}},'discard-source'(){dirtySource=false;closeModal();setView('canvas');},'copy-agent':()=>copy(agentPrompt()),'review-agent':reviewAgent,'apply-agent'(){if(!window.pendingDeck)return;snapshot();deck=window.pendingDeck;window.pendingDeck=null;index=Math.min(index,deck.slides.length-1);dirtySource=false;changed();closeModal();log('外部の変更を適用しました。');},'download-schema'(){download('slide-studio-schema.json',JSON.stringify({version:1,layouts,example:sample(),operations:[{op:'update',id:'slide-id',changes:{title:'新しいタイトル'}},{op:'add',index:1,slide:newSlide()},{op:'delete',id:'slide-id'},{op:'move',id:'slide-id',index:2},{op:'theme',changes:{background:'#000000'}}]},null,2));},'connect-bridge':connectBridge,'test-cue':()=>sendCue(true),'bridge-help'(){showModal('<h2>ローカル連携</h2><p>ソース一式のフォルダで <code>node server.mjs</code> を起動し、表示されたローカルURLを開いてください。トークンを接続欄に入力します。</p><p>AIは <code>project/deck.json</code> を編集できます。外部の変更は接続中の画面に通知され、確認して読み込めます。</p><p>TouchDesignerのWebSocket DATを <code>ws://127.0.0.1:4317/?token=起動時のトークン</code> に接続してください。キューはJSONで届きます。</p><p>ブラウザの内容をファイルへ渡す場合、プロジェクトを書き出して <code>project/deck.json</code> に配置してください。起動直後のブラウザでも「ファイルに保存」ボタンから保存できます。</p><div class="modal-actions"><button data-action="close-modal">閉じる</button></div>');},'asset-url'(){showModal('<h2>URLから素材を追加</h2><div class="field"><label>名前</label><input id="url-name" placeholder="作品記録"></div><div class="field"><label>URL</label><input id="url-src" placeholder="https://…/video.mp4"></div><div class="field"><label>種類</label><select id="url-type"><option value="image">画像</option><option value="video">動画</option><option value="audio">音声</option></select></div><p>共有先でもアクセスできる、素材ファイルの直接URLを指定してください。</p><div class="modal-actions"><button data-action="close-modal">キャンセル</button><button class="primary" data-action="add-url">追加</button></div>');},'add-url'(){try{const src=safeSrc($('#url-src').value.trim());if(!src)throw Error('URLが必要です');snapshot();deck.assets.push({id:uid(),name:$('#url-name').value.trim()||'URL asset',type:$('#url-type').value,src});panel='assets';changed();closeModal();}catch(e){toast(e.message);}},validate:checkDeck,'clear-log'(){logs=[];$('#logs').innerHTML='';},help,palette,'close-modal':closeModal};
document.addEventListener('click',e=>{const command=e.target.closest('[data-command]');if(command){closeModal();actions[command.dataset.command]?.();return;}const b=e.target.closest('[data-action]');if(b){Promise.resolve().then(()=>actions[b.dataset.action]?.()).catch(err=>{log(err.message,'warn');toast(err.message);});return;}const p=e.target.closest('[data-panel]');if(p){panel=p.dataset.panel;renderSidebar();return;}const v=e.target.closest('[data-view]');if(v){setView(v.dataset.view);return;}const s=e.target.closest('[data-slide]');if(s){selectSlide(Number(s.dataset.slide));if(view==='overview')setView('canvas');return;}const a=e.target.closest('[data-assign]');if(a){snapshot();current().assetId=a.dataset.assign;if(!['split','media'].includes(current().layout))current().layout='split';changed();toast('素材を割り当てました');return;}const remove=e.target.closest('[data-remove-asset]');if(remove){snapshot();const id=remove.dataset.removeAsset;deck.assets=deck.assets.filter(a=>a.id!==id);deck.slides.forEach(s=>{if(s.assetId===id)s.assetId='';});changed();return;}const pn=e.target.closest('[data-presenter-nav]');if(pn)channel?.postMessage({type:'navigate',direction:pn.dataset.presenterNav});});
document.addEventListener('change',e=>{const el=e.target,key=el.dataset.field;if(key){let value=el.type==='checkbox'?el.checked:el.type==='number'||el.type==='range'?Number(el.value):el.value;if(key.startsWith('media.')){const next={...current().media,[key.slice(6)]:value};if(next.end>0&&next.end<=next.start){toast('終了位置は開始位置より後にしてください');renderInspector();return;}snapshot();current().media=next;}else if(key.startsWith('theme.')){snapshot();deck.theme[key.slice(6)]=value;}else if(key==='author'){snapshot();deck.author=value;}else{snapshot();current()[key]=value;}changed();}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const q=e.target.value.toLowerCase();$('#search-results').innerHTML=deck.slides.map((s,i)=>({s,i})).filter(({s})=>(s.title+' '+s.body+' '+s.notes).toLowerCase().includes(q)).map(({s,i})=>`<div class="search-result" data-slide="${i}">${i+1}. ${esc(s.title)}</div>`).join('');}if(e.target.id==='source-editor'){dirtySource=true;$('#source-error').textContent='未適用の変更';}if(e.target.id==='command-search'){const q=e.target.value.toLowerCase();$$('[data-command]').forEach(b=>b.hidden=!b.textContent.toLowerCase().includes(q));}});
$('#deck-name').addEventListener('change',e=>{snapshot();deck.name=e.target.value||'Untitled';changed();});$('#notes').addEventListener('change',e=>updateSlide('notes',e.target.value,false));$('#zoom').addEventListener('change',fitStage);$('#media-input').addEventListener('change',async e=>{await addFiles(e.target.files);e.target.value='';});$('#project-input').addEventListener('change',async e=>{if(e.target.files[0])await importProject(e.target.files[0]);e.target.value='';});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'){e.preventDefault();actions['export-json']();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();palette();return;}if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='z'&&!typing){e.preventDefault();e.shiftKey?redo():undo();return;}if(e.key==='Escape'&&presenting){exitPresent();return;}if(typing||$('#modal')?.open)return;if(isPresenter){if(['ArrowRight','ArrowLeft',' '].includes(e.key)){e.preventDefault();channel?.postMessage({type:'navigate',direction:e.key==='ArrowLeft'?'previous':'next'});}return;}if(e.key==='F5'){e.preventDefault();startPresent();}if(['ArrowRight','ArrowLeft',' '].includes(e.key)){if(!presenting&&globalThis.studioHasSelection?.())return;e.preventDefault();e.key==='ArrowLeft'?previous():advance();}if(e.key.toLowerCase()==='b'&&presenting)actions.blackout();});
document.addEventListener('dragstart',e=>{const row=e.target.closest('[data-slide]');if(row){dragIndex=Number(row.dataset.slide);e.dataTransfer.setData('text/plain',String(dragIndex));e.dataTransfer.effectAllowed='move';}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')||e.target.closest('[data-slide]'))e.preventDefault();});document.addEventListener('drop',async e=>{if(e.dataTransfer.files.length){e.preventDefault();const files=[...e.dataTransfer.files];const project=files.find(f=>/\.(slide|json|md)$/.test(f.name));if(project)await importProject(project);else await addFiles(files);return;}const row=e.target.closest('[data-slide]');if(row&&dragIndex!==null){e.preventDefault();moveSlide(dragIndex,Number(row.dataset.slide));dragIndex=null;}});document.addEventListener('dragend',()=>dragIndex=null);
$$('.splitter').forEach(el=>el.addEventListener('pointerdown',e=>{el.setPointerCapture(e.pointerId);const right=el.dataset.resize==='right',start=e.clientX,initial=(right?$('#inspector'):$('#sidebar')).clientWidth;const move=ev=>{document.documentElement.style.setProperty(right?'--right':'--left',Math.max(170,Math.min(500,initial+(right?-1:1)*(ev.clientX-start)))+'px');fitStage();};const end=()=>{el.removeEventListener('pointermove',move);el.removeEventListener('pointerup',end);};el.addEventListener('pointermove',move);el.addEventListener('pointerup',end);}));window.addEventListener('resize',fitStage);document.addEventListener('fullscreenchange',()=>{if(presenting&&!document.fullscreenElement&&$('#presentation').hidden===false)exitPresent();});
async function init(){try{initChannel();}catch(e){log('発表者画面の同期はローカルサーバーで利用してください。','warn');}if(isPresenter){document.body.classList.add('presenter-page');document.body.innerHTML='<div id="presenter-root" class="presenter-layout"></div>';renderPresenter();channel?.postMessage({type:'request'});let started=Date.now();setInterval(()=>{const t=Math.floor((Date.now()-started)/1000);if($('#timer'))$('#timer').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');},1000);document.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='r')started=Date.now();});return;}try{db=await initDB();const saved=await stored('deck');if(saved)deck=validate(saved);}catch(e){log('自動保存が使えません。プロジェクトをファイル保存してください。','warn');}renderAll();$('#save-state').textContent=db?'自動保存済み':'ファイル保存が必要';log('Workspace ready. プロジェクトはこのブラウザに保存されます。');if(location.hostname==='127.0.0.1'||location.hostname==='localhost')await initLocal();globalThis.STUDIO_EDITOR_READY=true;if(globalThis.workspaceBootstrap)await workspaceBootstrap();}
async function initLocal(){try{const res=await fetch('/api/info');if(!res.ok)return;const info=await res.json();if(info.bridge){localConnected=true;$('#status-left').innerHTML='● Local workspace <button data-action="save-local" style="padding:0 8px;font-size:12px">ファイルに保存</button><button data-action="load-local" style="padding:0 8px;font-size:12px">ファイルから開く</button>';log('ローカルファイル連携が利用できます。接続パネルでトークンを設定してください。');}}catch{}}
actions['save-local']=async()=>{if(!bridgeToken){panel='bridge';renderSidebar();toast('起動時のトークンを入力して接続してください');return;}const r=await fetch('/api/project',{method:'PUT',headers:{'Content-Type':'application/json','Authorization':'Bearer '+bridgeToken},body:JSON.stringify(deck)});if(!r.ok)throw Error('ファイル保存失敗: '+r.status);log('project/deck.jsonに保存しました。');toast('ローカルファイルに保存しました');};
actions['load-local']=async()=>{if(!bridgeToken){panel='bridge';renderSidebar();toast('接続トークンを設定してください');return;}const r=await fetch('/api/project',{headers:{Authorization:'Bearer '+bridgeToken}});if(!r.ok)throw Error('ファイル読み込み失敗: '+r.status);showRemoteReview(validate(await r.json()));};
init().catch(e=>{console.error(e);log(e.message,'warn');});
